import React, { Component } from 'react';
import Moment from 'react-moment';
import moment from 'moment';
import Axios from 'axios';
import { Link } from 'react-router-dom';
import {CONFIGURATION} from '../../utils/configuration';

export default class ListEntry extends Component {
  constructor(props) {
    super(props);
  }

  deleteEntry(entry) {
    let auth = {
      method: 'DELETE',
      url: `${CONFIGURATION.API_ROOT}/mic/${entry._id}`,
      headers: {
        authorization: window.sessionStorage.getItem('token')
      }
    };

    Axios(auth)
      .then((res) => {
        window.location.reload();
      })
      .catch((err) => {
        console.log(err);
      });
  }

  nextDay(days) {
    let day;
    for (var i = 0; i < days.length; i++) {
      var today = moment().startOf('day');
      var currentDay = moment(days[i])
      if(currentDay > today) {
        day = currentDay;
        break;
      }
    }
    return day;
  }

  render() {
    console.log(this.props.entry);
    return (
      <tr>
        <td>
          Start - <Moment format="MMM D, YYYY">{this.props.entry.days[0]}</Moment>
          <br/>
          {
            this.props.entry.repeatForever != true && this.nextDay(this.props.entry.days)?
            <div>Next - <b><Moment format="MMM D, YYYY">{this.nextDay(this.props.entry.days)}</Moment></b></div>
            :<div>Next - <b><Moment format="MMM D, YYYY">{this.props.entry.nextPerformanceDay}</Moment></b></div>
          }
          {this.props.entry.repeatFrequency?
           this.props.entry.repeatFrequency !== 'custom'?
            <div><span className="subtitle">Repeat Frequency - </span>{this.props.entry.repeatFrequency}
              <br/><span className="subtitle"> Repeats Until - </span> 
                { this.props.entry.repeatForever != true ? <Moment format="MMM D, YYYY">{this.props.entry.days[this.props.entry.days.length - 1]}</Moment> : null}
                { this.props.entry.repeatForever == true ? (<span>{`Indefinitely - ${this.props.entry.repeatFrequency} from `} <Moment format="MMM D, YYYY">{this.props.entry.days[0]}</Moment></span>) : null }
            </div>
            :<div><span className="subtitle">Repeat Frequency - </span> {this.props.entry.repeatFrequency}
            <br/><span className="subtitle"> Last Date - </span><Moment format="MMM D, YYYY">{this.props.entry.days[this.props.entry.days.length - 1]}</Moment>
            </div>
            :null
          }
        </td>
        <td>{this.props.entry.name}</td>
        <td>{this.props.entry.venueName}</td>
        <td>{this.props.entry.venueCity?this.props.entry.venueCity:''}</td>
        <td><span className="subtitle">Name - </span> {this.props.entry.hostName}
          <br/> <span className="subtitle"> Email - </span>{this.props.entry.hostEmail?this.props.entry.hostEmail:''}
          <br/> <span className="subtitle"> Phone - </span>{this.props.entry.hostPhone?this.props.entry.hostPhone:''}
        </td>

        <td className='buttonContainer'>
          <button role='submit' className='btn btn-danger btn-sm deleteMic' onClick={() => this.deleteEntry(this.props.entry)}>
            Delete
          </button>

          <Link to={`/Mic/${this.props.entry._id}`}>
            <button role='button' className='btn btn-info btn-sm deleteMic'>
              View
            </button>
          </Link>
        </td>
      </tr>
    );
  }
}



